import{z as i,x as B,o as e,c as l,q as A,j as t,D as E,d as o,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"门限签名与 MPC 直觉","description":"","frontmatter":{"title":"门限签名与 MPC 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threshold-mpc.md","filePath":"cs/threshold-mpc.md","lastUpdated":1791063341000}'),d={name:"cs/threshold-mpc.md"};function p(h,a,c,D,m,_){const r=B("Mermaid");return e(),l("div",null,[a[2]||(a[2]=A('<h1 id="门限签名与-mpc-直觉" tabindex="-1">门限签名与 MPC 直觉 <a class="header-anchor" href="#门限签名与-mpc-直觉" aria-label="Permalink to &quot;门限签名与 MPC 直觉&quot;">​</a></h1><div class="epigraph"><p>门限签名让 $t$ 方一起签发，任何一方拿不到完整私钥。安全多方计算把「一起算 $f$」当成协议目标，中间值按共享走，输出才打开。</p><footer>—— 据 Yao 百万富翁问题；Goldreich, Micali and Wigderson；对照 Boneh, Lynn and Shacham 对门限的后续工程</footer></div><p>上一课<a href="/cs/shamir-secret-sharing">Shamir</a>重构后秘密又聚回一点。缺口是<strong>计算阶段也不聚合明文</strong>。本课直觉：门限 ECDSA/EdDSA 与 MPC 的诚实多数/恶意模型，不写可部署的协议抄本。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HSM 是单盒；组织要「五人中三人签字」。门限：KeyGen 分布式，Sign 交互，Verify 仍用普通公钥。MPC：各方输入保密，只揭示 \\(f(x_1,\\ldots)\\)。缺口是目标陈述与敌手模型，不是电路乱码的实现作业。</p><h3 id="中止与公平" tabindex="-1">中止与公平 <a class="header-anchor" href="#中止与公平" aria-label="Permalink to &quot;中止与公平&quot;">​</a></h3><p>恶意敌手可让协议中止。公平性（要么都得输出要么都不得）更贵。工程上常退让。</p><p><span class="marginnote">Yao；GMW。DKLS 等门限 ECDSA 是工程文献，本课不点具体利用。后课同态是另一条「算密文」的路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对比三种：重构再签（弱）、门限签（私钥永不出现）、通用 MPC。写诚实多数 vs 恶意、带广播 vs 点对点。指出 nonce 在门限 ECDSA 里仍危险，EdDSA/Schnorr 更贴线性。</p>',11)),(e(),t(s,null,{default:E(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E4%BB%BD%E9%A2%9D%E7%95%99%E4%B8%8B%22%5D%20--%3E%20SIGN%5B%22%E4%BA%A4%E4%BA%92%E4%BA%A7%E7%94%9F%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIGN%20--%3E%20PUB%5B%22%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E5%8F%AF%E9%AA%8C%22%5D%0A%20%20IN%5B%22%E7%A7%81%E6%9C%89%E8%BE%93%E5%85%A5%22%5D%20--%3E%20MPC%5B%22%E5%8D%8F%E8%AE%AE%E7%AE%97%20f%22%5D%0A%20%20MPC%20--%3E%20Y%5B%22%E5%8F%AA%E6%89%93%E5%BC%80%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小特权：单人无法签。这服务治理，不服务「防所有侧信道」——交互本身有时序。网络异步下要小心同步假设。同态加密下一课把计算丢给持密文的一方，交互模式不同。</p><p><span class="marginnote">直觉类比：门限 3/5 像保险柜要三把钥匙同时插——任何两个人凑不齐份额就开不了柜。但「签出一份有效签名」不需要先拼出整把钥匙：三人各自用份额算出一部分，拼起来的是签名本身，私钥从头到尾没在任何人手里完整出现过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供门限 nonce 复用的攻击步骤。同态直觉下一课：密文上加乘，解密才见结果。</p><p>三条路线的私钥暴露点对比：</p>',6)),(e(),t(s,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%225%20%E4%BA%BA%E5%90%84%E6%8C%81%203%2F5%20%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20R%5B%22%E6%96%B9%E6%A1%88A%3A%20%E5%85%88%E9%87%8D%E6%9E%84%E5%86%8D%E7%AD%BE%22%5D%0A%20%20R%20--%3E%20RX%5B%22%E6%98%8E%E6%96%87%E7%A7%81%E9%92%A5%E7%9F%AD%E6%9A%82%E8%81%9A%E5%90%88%3A%20%E5%8D%95%E7%82%B9%E9%A3%8E%E9%99%A9%E5%9B%9E%E6%9D%A5%E4%BA%86%22%5D%0A%20%20K%20--%3E%20T%5B%22%E6%96%B9%E6%A1%88B%3A%20%E9%97%A8%E9%99%90%E7%AD%BE%E5%90%8D%22%5D%0A%20%20T%20--%3E%20TX%5B%22%E4%BA%A4%E4%BA%92%E7%9B%B4%E6%8E%A5%E4%BA%A7%E5%87%BA%E7%AD%BE%E5%90%8D%3A%20%E7%A7%81%E9%92%A5%E6%B0%B8%E4%B8%8D%E8%81%9A%E5%90%88%22%5D%0A%20%20T%20--%3E%20TH%5B%22%E5%B0%91%E4%BA%8E%203%20%E4%BA%BA%E6%8E%A8%E4%B8%8D%E5%87%BA%E4%BB%BB%E4%BD%95%E4%B8%9C%E8%A5%BF%22%5D%0A%20%20K%20--%3E%20M%5B%22%E6%96%B9%E6%A1%88C%3A%20%E9%80%9A%E7%94%A8%20MPC%22%5D%0A%20%20M%20--%3E%20MX%5B%22%E4%BB%BB%E6%84%8F%E5%87%BD%E6%95%B0%E9%83%BD%E8%83%BD%E7%AE%97%3A%20%E4%BA%A4%E4%BA%92%E4%B8%8E%E6%88%90%E6%9C%AC%E6%9B%B4%E9%AB%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享若重构再签，秘密又单点化。</li><li>门限签名：交互产出，公钥仍单把。</li><li>MPC 把任意 \\(f\\) 当协议；模型要写清恶意与中止。</li><li>下一课：同态加密直觉。</li><li>出处：Yao；Goldreich, Micali and Wigderson；Shamir, 1979。</li></ul><p><span class="marginnote">常见误区：初学者容易以为「份额多的人权力大」——标准 Shamir 份额是等权的：任取 3 份都能重构，某人多拿 2 份也不会更容易。门限说的是「几人可解」，不是「谁多谁少」。</span></p><p><span class="marginnote">为什么重要：门限 ECDSA 里 nonce 复用一次就可能泄露私钥——单机签名尚且如此，多方交互让 nonce 随机性的审计更难。这就是工程文献更偏爱线性结构的 EdDSA/Schnorr 类协议做门限化的原因。</span></p>',4))])}const f=i(d,[["render",p]]);export{S as __pageData,f as default};
